import json
import copy

def var_key(category, value):
    return f"{category}:{value}"

def make_domains(categories):
    domains = {}
    for cat, values in categories.items():
        for v in values:
            domains[var_key(cat, v)] = set(range(1, 7))
    return domains

def apply_fixed(domains, fixed_assignments):
    for var, val in fixed_assignments.items():
        domains[var] = {val}

def all_diff_prune(domains, category_vars):
    changed = False
    for cat, vars_in_cat in category_vars.items():
        assigned_vals = set()
        for v in vars_in_cat:
            if len(domains[v]) == 1:
                assigned_vals |= domains[v]
        for v in vars_in_cat:
            if len(domains[v]) > 1:
                before = set(domains[v])
                domains[v] -= assigned_vals
                if domains[v] != before:
                    changed = True
                if len(domains[v]) == 0:
                    return None, True
    return domains, changed

def unify_equal_groups(domains, eq_groups):
    changed = False
    for group in eq_groups:
        inter = set(range(1,7))
        for var in group:
            inter &= domains[var]
        if not inter:
            return None, True
        for var in group:
            before = set(domains[var])
            if domains[var] != inter:
                domains[var] = set(inter)
                changed = True
            if len(domains[var]) == 0:
                return None, True
    return domains, changed

def arc_reduce_left_of(domains, A, B):
    changed = False
    domA = domains[A]
    domB = domains[B]
    newA = set([a for a in domA if any(a < b for b in domB)])
    newB = set([b for b in domB if any(a < b for a in domA)])
    if not newA or not newB:
        return None, True
    if newA != domA:
        domains[A] = newA
        changed = True
    if newB != domB:
        domains[B] = newB
        changed = True
    return domains, changed

def arc_reduce_exactly_left(domains, A, B):
    changed = False
    domA = domains[A]
    domB = domains[B]
    newA = set([a for a in domA if (a+1) in domB])
    newB = set([b for b in domB if (b-1) in domA])
    if not newA or not newB:
        return None, True
    if newA != domA:
        domains[A] = newA
        changed = True
    if newB != domB:
        domains[B] = newB
        changed = True
    return domains, changed

def arc_reduce_adjacent(domains, A, B):
    changed = False
    domA = domains[A]
    domB = domains[B]
    newA = set([a for a in domA if (a-1) in domB or (a+1) in domB])
    newB = set([b for b in domB if (b-1) in domA or (b+1) in domA])
    if not newA or not newB:
        return None, True
    if newA != domA:
        domains[A] = newA
        changed = True
    if newB != domB:
        domains[B] = newB
        changed = True
    return domains, changed

def arc_reduce_distance(domains, A, B, k):
    changed = False
    domA = domains[A]
    domB = domains[B]
    newA = set([a for a in domA if (a-k) in domB or (a+k) in domB])
    newB = set([b for b in domB if (b-k) in domA or (b+k) in domA])
    if not newA or not newB:
        return None, True
    if newA != domA:
        domains[A] = newA
        changed = True
    if newB != domB:
        domains[B] = newB
        changed = True
    return domains, changed

def propagate(domains, category_vars, eq_groups, binary_constraints):
    while True:
        any_change = False
        # All-diff
        res, changed = all_diff_prune(domains, category_vars)
        if res is None:
            return None
        domains = res
        any_change = any_change or changed

        # Equality groups
        res, changed = unify_equal_groups(domains, eq_groups)
        if res is None:
            return None
        domains = res
        any_change = any_change or changed

        # Binary constraints arc reduction
        for cons in binary_constraints:
            typ = cons['type']
            if typ == 'left_of':
                A, B = cons['A'], cons['B']
                res, changed = arc_reduce_left_of(domains, A, B)
            elif typ == 'exactly_left':
                A, B = cons['A'], cons['B']
                res, changed = arc_reduce_exactly_left(domains, A, B)
            elif typ == 'adjacent':
                A, B = cons['A'], cons['B']
                res, changed = arc_reduce_adjacent(domains, A, B)
            elif typ == 'distance':
                A, B, k = cons['A'], cons['B'], cons['k']
                res, changed = arc_reduce_distance(domains, A, B, k)
            else:
                res, changed = domains, False
            if res is None:
                return None
            domains = res
            any_change = any_change or changed

        if not any_change:
            break
    return domains

def is_complete(domains):
    return all(len(v) == 1 for v in domains.values())

def select_unassigned_variable(domains):
    # MRV heuristic
    unassigned = [(len(v), k) for k, v in domains.items() if len(v) > 1]
    if not unassigned:
        return None
    unassigned.sort()
    return unassigned[0][1]

def backtrack(domains, category_vars, eq_groups, binary_constraints):
    domains = propagate(domains, category_vars, eq_groups, binary_constraints)
    if domains is None:
        return None
    if is_complete(domains):
        return domains
    var = select_unassigned_variable(domains)
    if var is None:
        return domains
    domain_vals = sorted(domains[var])
    for val in domain_vals:
        new_domains = copy.deepcopy(domains)
        new_domains[var] = {val}
        result = backtrack(new_domains, category_vars, eq_groups, binary_constraints)
        if result is not None:
            return result
    return None

def main():
    # Define categories and values
    categories = {
        "Name": ["Eric", "Alice", "Arnold", "Carol", "Peter", "Bob"],
        "Style": ["mediterranean", "modern", "craftsman", "ranch", "colonial", "victorian"],
        "Music": ["country", "hip hop", "pop", "jazz", "classical", "rock"],
        "Hobby": ["cooking", "painting", "photography", "woodworking", "gardening", "knitting"],
    }

    # Build variable groups per category
    category_vars = {cat: [var_key(cat, v) for v in vals] for cat, vals in categories.items()}

    # Initialize domains
    domains = make_domains(categories)

    # Equality groups (must be in the same house)
    eq_groups = [
        # Mediterranean = Hip hop = Carol
        [var_key("Style", "mediterranean"), var_key("Music", "hip hop"), var_key("Name", "Carol")],
        # Eric = Ranch = Gardening
        [var_key("Name", "Eric"), var_key("Style", "ranch"), var_key("Hobby", "gardening")],
        # Craftsman = Arnold
        [var_key("Style", "craftsman"), var_key("Name", "Arnold")],
        # Woodworking = Victorian
        [var_key("Hobby", "woodworking"), var_key("Style", "victorian")],
        # Alice = Photography
        [var_key("Name", "Alice"), var_key("Hobby", "photography")],
    ]

    # Fixed assignments
    fixed_assignments = {
        var_key("Music", "rock"): 5,         # Clue 1
        var_key("Music", "country"): 1,      # Clue 11
        var_key("Name", "Bob"): 3            # Clue 15
    }
    apply_fixed(domains, fixed_assignments)

    # Binary constraints
    binary_constraints = [
        # Clue 2: classical next to woodworking
        {"type": "adjacent", "A": var_key("Music", "classical"), "B": var_key("Hobby", "woodworking")},
        # Clue 4: two houses between Arnold and Victorian (distance 3)
        {"type": "distance", "A": var_key("Name", "Arnold"), "B": var_key("Style", "victorian"), "k": 3},
        # Clue 5: jazz directly left of Eric
        {"type": "exactly_left", "A": var_key("Music", "jazz"), "B": var_key("Name", "Eric")},
        # Clue 6: hip hop left of knitting
        {"type": "left_of", "A": var_key("Music", "hip hop"), "B": var_key("Hobby", "knitting")},
        # Clue 12: one house between painting and colonial (distance 2)
        {"type": "distance", "A": var_key("Hobby", "painting"), "B": var_key("Style", "colonial"), "k": 2},
    ]

    solution_domains = backtrack(domains, category_vars, eq_groups, binary_constraints)
    if solution_domains is None:
        raise RuntimeError("No solution found")

    # Build mapping from position to attributes
    pos_to_name = {}
    pos_to_style = {}
    pos_to_music = {}
    pos_to_hobby = {}

    for name in categories["Name"]:
        pos = next(iter(solution_domains[var_key("Name", name)]))
        pos_to_name[pos] = name
    for style in categories["Style"]:
        pos = next(iter(solution_domains[var_key("Style", style)]))
        pos_to_style[pos] = style
    for mus in categories["Music"]:
        pos = next(iter(solution_domains[var_key("Music", mus)]))
        pos_to_music[pos] = mus
    for hob in categories["Hobby"]:
        pos = next(iter(solution_domains[var_key("Hobby", hob)]))
        pos_to_hobby[pos] = hob

    header = ["House", "name", "style of house", "favorite music genres", "hobby"]
    rows = []
    for house in range(1, 7):
        row = [
            str(house),
            pos_to_name.get(house, ""),
            pos_to_style.get(house, ""),
            pos_to_music.get(house, ""),
            pos_to_hobby.get(house, "")
        ]
        rows.append(row)

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    main()
